    if (last_slash == NULL) {
        // No directory part
        strcpy(dir_path, ".");
        strcpy(filename, path);
    } else if (last_slash == path) {
        // Root directory
        strcpy(dir_path, "/");
        strcpy(filename, last_slash + 1);
